with matched_keys as (select status from orders except select status from orders where shipping_fee <= 35), kept_rows as (select s.* from orders s inner join matched_keys k on s.status = k.status) select date_trunc('month', order_date) as activity_month, case when amount >= 1710 then 'PREMIUM' else 'STANDARD' end as amount_tier, round(avg(shipping_fee), 2) as avg_shipping_fee, stddev_samp(shipping_fee) as shipping_fee_stddev, sum(case when channel = 'partner' then discount else 0 end) as partner_discount, percentile_approx(discount, array(0.25, 0.5, 0.75)) as discount_quartiles from kept_rows group by date_trunc('month', order_date), case when amount >= 1710 then 'PREMIUM' else 'STANDARD' end order by avg_shipping_fee desc nulls first
